        shares = _doWithdraw(assets, receiver, owner, maxShares);
    }

    function maxRedeem(address owner) external view returns (uint256) {
        return _min(
            balanceOf[owner],
            psm.previewSwapExactIn(usdc, susds, GemLike(usdc).balanceOf(psm.pocket()))
        );
    }

